kql.query:
let OfficeProcs = dynamic(["outlook.exe", "winword.exe", "excel.exe", "powerpnt.exe"]);
let WebDavMarkers = dynamic(["@SSL", "DavWWWRoot", "http://", "https://"]);
let OfficeWebClient =
    DeviceEvents
    | where Timestamp > ago(90d)
    | where InitiatingProcessFileName in~ (OfficeProcs)
    | where ActionType has_any ("Service", "NamedPipe") or tostring(AdditionalFields) has "WebClient"
    | project Timestamp, DeviceName, Source = "DeviceEvents", ActionType, Process = InitiatingProcessFileName, Detail = strcat(FileName, " | ", tostring(AdditionalFields)), Account = InitiatingProcessAccountName;
let OfficeUncChild =
    DeviceProcessEvents
    | where Timestamp > ago(90d)
    | where InitiatingProcessFileName in~ (OfficeProcs)
    | where ProcessCommandLine has @"\\" or ProcessCommandLine has_any (WebDavMarkers)
    | project Timestamp, DeviceName, Source = "DeviceProcessEvents", ActionType = "ProcessCreated", Process = InitiatingProcessFileName, Detail = ProcessCommandLine, Account = InitiatingProcessAccountName;
union OfficeWebClient, OfficeUncChild
| order by Timestamp desc
